    async def update(
        self,
        id: str,
        *,
        revision_number: str,
        vendor_id: str | NotGiven = NOT_GIVEN,
        vendor_address: AddressUpdateInput | NotGiven = NOT_GIVEN,
        payables_account_id: str | NotGiven = NOT_GIVEN,
        transaction_date: _dt.date | NotGiven = NOT_GIVEN,
        due_date: _dt.date | NotGiven = NOT_GIVEN,
        ref_number: str | NotGiven | None = NOT_GIVEN,
        terms_id: str | NotGiven = NOT_GIVEN,
        memo: str | NotGiven | None = NOT_GIVEN,
        exchange_rate: float | NotGiven = NOT_GIVEN,
        clear_expense_lines: bool | NotGiven = NOT_GIVEN,
        expense_lines: Sequence[ExpenseLineUpdateInput] | NotGiven = NOT_GIVEN,
        clear_item_lines: bool | NotGiven = NOT_GIVEN,
        item_lines: Sequence[ItemLineUpdateInput] | NotGiven = NOT_GIVEN,
        item_group_lines: Sequence[ItemGroupLineUpdateInput] | NotGiven = NOT_GIVEN,
        end_user_id: str | None = None,
        conductor_end_user_id: str | None = None,
        idempotency_key: str | None = None,
        timeout: float | None = None,
        total_timeout: float | None = None,
        max_retries: int | None = None,
        server_timeout: int | None = None,
    ) -> Bill:
        """Update a bill.

        Changes the fields you send on an existing bill and leaves omitted fields unchanged. Requires the current `revisionNumber`. A stale `revisionNumber` returns `409 QBD_REVISION_NUMBER_STALE`: retrieve the bill, reapply your change and send the new revision. Sending a line array replaces all existing lines of that kind. Line arrays you omit stay unchanged: when you send only some of them, the API first reads the transaction (a separate read in the request log) and keeps the omitted lines by ID, because QuickBooks would otherwise delete them. See [Updates and line items](https://www.desktopaccountingapi.com/docs/quickbooks/updates-and-line-items/).

        Operation ``qbd.bills.update``: ``POST /v1/quickbooks-desktop/bills/{id}``.

        Args:
            id: QuickBooks ID of the bill.
            revision_number: Current revision of this bill. Send it unchanged when updating; a stale value is rejected. QuickBooks changes it at most once per second, so a second edit within the same second keeps the same value. This API spaces its own consecutive writes to one object by over a second; edits made elsewhere in the same second are not detected.
            vendor_id: ID of the vendor for this bill.
            vendor_address: See the API reference.
            payables_account_id: ID of the payables account for this bill.
            transaction_date: Date of this bill (YYYY-MM-DD).
            due_date: Date payment of this bill is due (YYYY-MM-DD).
            ref_number: Reference number of this bill, such as an invoice or check number. Case-sensitive. Pass ``None`` to clear it.
            terms_id: ID of the terms for this bill.
            memo: Internal memo for this bill; shown in reports, not on printed forms. Pass ``None`` to clear it.
            exchange_rate: Exchange rate from this bill's currency to the home currency.
            clear_expense_lines: Clear expense lines of this bill. Replaces every existing line when present: keep a line by sending its id, add one with id "-1", omit the array to leave lines unchanged.
            expense_lines: Expense lines entries for this bill. When present, replaces this array: keep an existing entry by sending its id (an id alone leaves it unchanged), add one with id "-1"; existing entries you leave out are deleted. Omit the array to keep these entries unchanged, also when you send itemLines or itemGroupLines: the API then reads the bill first and keeps every existing entry of each omitted array by ID. An empty array deletes them all, as long as the bill keeps at least one line.
            clear_item_lines: Clear item lines of this bill. Replaces every existing line when present: keep a line by sending its id, add one with id "-1", omit the array to leave lines unchanged.
            item_lines: Item lines entries for this bill. When present, replaces this array: keep an existing entry by sending its id (an id alone leaves it unchanged), add one with id "-1"; existing entries you leave out are deleted. Omit the array to keep these entries unchanged, also when you send expenseLines or itemGroupLines: the API then reads the bill first and keeps every existing entry of each omitted array by ID. An empty array deletes them all, as long as the bill keeps at least one line.
            item_group_lines: Item group lines entries for this bill. When present, replaces this array: keep an existing entry by sending its id (an id alone leaves it unchanged), add one with id "-1"; existing entries you leave out are deleted. Omit the array to keep these entries unchanged, also when you send expenseLines or itemLines: the API then reads the bill first and keeps every existing entry of each omitted array by ID. An empty array deletes them all, as long as the bill keeps at least one line.
            end_user_id: End user (``eu_...``) whose QuickBooks company file to use. Defaults to the client's ``end_user_id``.
            conductor_end_user_id: Alias of ``end_user_id`` with Conductor's name, for code ported from ``conductor-py``. Passing both with different values raises ``DaapiError``.
            idempotency_key: Makes the write safe to retry (``Idempotency-Key``). Defaults to a new UUID that is reused on every retry of this call.
            timeout: Client-side timeout in seconds for each HTTP attempt; also the time budget for waiting on a request that is still running in QuickBooks. Defaults to the client's ``timeout``.
            total_timeout: Time budget in seconds for the whole call: every attempt, retry backoff and the wait for a pending request. Defaults to the client's ``total_timeout`` (none).
            max_retries: Retries for network errors, 429 and retryable 5xx responses. Defaults to the client's ``max_retries``.
            server_timeout: Seconds the API waits for QuickBooks before answering (``Daapi-Timeout-Seconds``, 1-300). Defaults to the client's ``server_timeout`` or the API default.

        Returns:
            The Bill object.
        """
        return await self._client._request(
            _QBD_BILLS_UPDATE,
            "POST",
            "/v1/quickbooks-desktop/bills/" + _pp("id", id),
            cast_to=Bill.from_wire,
            body={
                "revisionNumber": revision_number,
                "vendorId": vendor_id,
                "vendorAddress": vendor_address,
                "payablesAccountId": payables_account_id,
                "transactionDate": transaction_date,
                "dueDate": due_date,
                "refNumber": ref_number,
                "termsId": terms_id,
                "memo": memo,
                "exchangeRate": exchange_rate,
                "clearExpenseLines": clear_expense_lines,
                "expenseLines": expense_lines,
                "clearItemLines": clear_item_lines,
                "itemLines": item_lines,
                "itemGroupLines": item_group_lines,
            },
            end_user_id=end_user_id,
            conductor_end_user_id=conductor_end_user_id,
            idempotency_key=idempotency_key,
            timeout=timeout,
            total_timeout=total_timeout,
            max_retries=max_retries,
            server_timeout=server_timeout,
        )

    async def void(
        self,
        id: str,
        *,
        end_user_id: str | None = None,
        conductor_end_user_id: str | None = None,
        idempotency_key: str | None = None,
        timeout: float | None = None,
        total_timeout: float | None = None,
        max_retries: int | None = None,
        server_timeout: int | None = None,
    ) -> BillVoided:
        """Void a bill.

        Voids a bill: QuickBooks keeps the record but sets its amounts to zero. Use void instead of delete when the bill must stay in the audit trail. Send an `Idempotency-Key` to make retries safe.

        Operation ``qbd.bills.void``: ``POST /v1/quickbooks-desktop/bills/{id}/void``.

        Args:
            id: QuickBooks ID of the bill.
            end_user_id: End user (``eu_...``) whose QuickBooks company file to use. Defaults to the client's ``end_user_id``.
            conductor_end_user_id: Alias of ``end_user_id`` with Conductor's name, for code ported from ``conductor-py``. Passing both with different values raises ``DaapiError``.
            idempotency_key: Makes the write safe to retry (``Idempotency-Key``). Defaults to a new UUID that is reused on every retry of this call.
            timeout: Client-side timeout in seconds for each HTTP attempt; also the time budget for waiting on a request that is still running in QuickBooks. Defaults to the client's ``timeout``.
            total_timeout: Time budget in seconds for the whole call: every attempt, retry backoff and the wait for a pending request. Defaults to the client's ``total_timeout`` (none).
            max_retries: Retries for network errors, 429 and retryable 5xx responses. Defaults to the client's ``max_retries``.
            server_timeout: Seconds the API waits for QuickBooks before answering (``Daapi-Timeout-Seconds``, 1-300). Defaults to the client's ``server_timeout`` or the API default.

        Returns:
            The BillVoided object.
        """
        return await self._client._request(
            _QBD_BILLS_VOID,
            "POST",
            "/v1/quickbooks-desktop/bills/" + _pp("id", id) + "/void",
            cast_to=BillVoided.from_wire,
            end_user_id=end_user_id,
            conductor_end_user_id=conductor_end_user_id,
            idempotency_key=idempotency_key,
            timeout=timeout,
            total_timeout=total_timeout,
            max_retries=max_retries,
            server_timeout=server_timeout,
        )
